 * Email → user id for the org's current active members: live membership rows
 * with status `active`. Keys are lower-cased so callers can match an address
 * case-insensitively.
 */
export async function mapActiveMemberEmails(
  orgId: OrgId,
): Promise<ReadonlyMap<string, UserId>> {
  const rows = getDb()
    .select({ userId: members.userId, email: users.email })
    .from(members)
    .innerJoin(users, eq(users.id, members.userId))
    .where(
      and(
        orgPredicate(members.orgId, orgId),
        eq(members.status, "active"),
        liveMemberPredicate(),
      ),
    )
    .all();

  const byEmail = new Map<string, UserId>();
  for (const row of rows) {
    const email = row.email.toLowerCase();
    if (!byEmail.has(email)) byEmail.set(email, row.userId as UserId);
  }
  return byEmail;
}

