/** Token bucket shared by every path that creates issues in bulk. */
const ISSUE_CREATE_BUCKET = "issue:create";

/** Tail of the in-flight import per org; see `serialiseImports`. */
const importTails = new Map<OrgId, Promise<void>>();

/**
 * Runs one import at a time per org. The checks and the write are separated
 * by awaits, so without this two uploads of the same key racing each other
 * would both be treated — and charged — as a first upload.
 */
async function serialiseImports<T>(
  orgId: OrgId,
  task: () => Promise<T>,
): Promise<T> {
  const previous = importTails.get(orgId) ?? Promise.resolve();
  const run = previous.then(task);
  const tail = run.then(
    () => undefined,
    () => undefined,
  );
  importTails.set(orgId, tail);
  try {
    return await run;
  } finally {
    if (importTails.get(orgId) === tail) importTails.delete(orgId);
  }
}

/**
 * Bulk import: every row becomes an issue, in file order, or nothing does.
 *
 * Gates run in the order tenant scope → project → replay → archived →
 * `issue:create` → per-project quota for the whole batch → rate allowance
 * (one unit per row); only then is the batch written, in one transaction.
 * A key the org has already imported short-circuits to the first result, and
 * a refused import leaves no ledger row, so its key stays unused.
 *
 * One `issues.imported` event stands in for the per-issue `issue.created`
 * events: search, usage and the audit log react to it; notifications and
 * outgoing webhooks deliberately do not.
 */
export async function importIssues(
  actor: Actor,
  input: ImportIssuesInput,
): Promise<IssueImportResult> {
  assertOrgScope(actor, input.orgId);

  const outcome = await serialiseImports(input.orgId, async () => {
    const project = requireFound(
      await projectRepo.findProjectById(input.orgId, input.projectId),
      "Project",
      input.projectId,
    );

    const earlier = await issueImportRepo.findImport(
      input.orgId,
      input.importKey,
    );
    if (earlier !== null) {
      assertCan(actor, "issue:create", projectResource(project));
      if (earlier.projectId !== project.id) {
        const imported = requireFound(
          await projectRepo.findProjectById(input.orgId, earlier.projectId),
          "Project",
          earlier.projectId,
        );
        assertCan(actor, "issue:create", projectResource(imported));
      }
      return { created: false, record: earlier };
    }

    assertNotArchived("Project", project.id, project);
    assertCan(actor, "issue:create", projectResource(project));

    const org = requireFound(
      await orgRepo.findOrgById(input.orgId),
      "Organization",
      input.orgId,
    );
    await assertIssueQuota(org, project, input.rows.length);

    const memberIdByEmail = await memberRepo.mapActiveMemberEmails(
      input.orgId,
    );
    const rows = input.rows.map((row) => ({
      title: row.title,
      description: row.description ?? null,
      status: row.status ?? "backlog",
      priority: row.priority ?? "none",
      assigneeId:
        row.assigneeEmail == null
          ? null
          : (memberIdByEmail.get(row.assigneeEmail.toLowerCase()) ?? null),
      dueAt: row.dueAt ?? null,
      labels: row.labels ?? [],
    }));

    const verdict = await consumeRateLimit(
      input.orgId,
      ISSUE_CREATE_BUCKET,
      rows.length,
    );
    if (!verdict.allowed) {
      throw new Error(
        `Issue creation rate limit reached; try again after ${verdict.resetAt}`,
      );
    }

    return issueImportRepo.insertImport({
      orgId: input.orgId,
      projectId: project.id,
      importKey: input.importKey,
      authorId: actor.userId,
      rows,
    });
  });

  const { record } = outcome;
  const issues = await issueImportRepo.listImportedIssues(record);

  if (outcome.created) {
    await emit("issues.imported", {
      ...actorEnvelope(actor),
      projectId: record.projectId,
      importKey: record.importKey,
      issueIds: record.issueIds,
    });
  }

  return {
    importKey: record.importKey,
    projectId: record.projectId,
    issues,
    replayed: !outcome.created,
  };
}

