    issueService.importIssues(t.actors.member, input),
    issueService.importIssues(t.actors.member, input),
  ]);
  expect(r1.replayed).toBe(false);
  expect(r2.replayed).toBe(true);
  expect(r2.issues).toEqual(r1.issues);
  expect(r1.issues.map((i) => i.number)).toEqual([2, 3]);
  expect(r1.issues[0]!.labelIds).toHaveLength(2);
