  const after = await usageRepo.getUsage(t.org.id);
  expect(after.issuesUsed - before.issuesUsed).toBe(2);
  const db = getDb().$client;
  console.log(db.prepare("select action, subject_kind, metadata, actor_id from activity_events").all());
  console.log(db.prepare("select name, color, description from labels").all());
  console.log(db.prepare("select subject_id, content from search_index").all());
  console.log(db.prepare("select count(*) c from notifications").all(), db.prepare("select count(*) c from webhook_deliveries").all());
  await expect(issueService.importIssues(t.actors.viewer, { ...input, importKey: "other-key-1" })).rejects.toThrow();
  await expect(issueService.importIssues(t.actors.member, { ...input, importKey: "big-key-111", rows: Array.from({ length: 61 }, () => input.rows[0]!) })).rejects.toThrow(/rate limit/);
  expect(db.prepare("select count(*) c from issues").get()).toEqual({ c: 3 });
});
